window.SKIM_PAPERS["1801.10198"] = {"concepts": [{"id": "transformer-decoder-t-d", "name": "Transformer Decoder (T-D): dropping the encoder", "tier": "minor", "parent": null, "summary": "A modification of the encoder-decoder transformer that deletes the encoder module entirely, leaving a single stack of decoder blocks that reads input and output as one continuous sequence. For a fixed hyper-parameter set this roughly halves the parameter count.", "explanation": "The standard transformer for sequence transduction is symmetric: an encoder stack over the source and a decoder stack over the target, with the decoder blocks carrying an extra encoder-decoder attention sublayer that reads the encoder's final states. The variant here (called T-D) removes the encoder stack and, with it, the encoder-decoder attention sublayer, so each block is left with only masked multi-head self-attention plus the position-wise feed-forward network. The paper notes this almost halves model parameters for a given hyper-parameter set. In the experiments the T-D stack was configured identically to the decoder half of the encoder-decoder baseline (the tensor2tensor hyper-parameter set transformer_base_v1, trained for 1 million steps), so the comparison isolates the architectural change rather than model size. The paper's reasoning is that on monolingual text-to-text tasks the encoder and decoder re-learn redundant information about language, and that folding them into one stack makes optimization easier. It also observes that nothing is lost in terms of connectivity: because the single stack uses self-attention over the concatenated sequence, when generating the next token the model attends over both the source region and the already-generated target region, which is what encoder-decoder attention plus decoder self-attention provided separately. The claim is empirical and hedged - the paper says it believes this allows easier optimization and observes the benefit at longer input lengths.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.2.3 (Transformer Decoder (T-D)); baseline contrast in Section 4.2.2; configuration in Section 5.2 (Model Training Details and Decoding).", "ownerPaper": "1801.10198", "sources": {"paperId": "1801.10198", "note": "Section 4.2.3 (Transformer Decoder (T-D)); baseline contrast in Section 4.2.2; configuration in Section 5.2 (Model Training Details and Decoding).", "sections": [], "pages": []}}, {"id": "transduction-as-single-sequence-lm", "name": "Transduction recast as single-sequence language modeling", "tier": "minor", "parent": null, "summary": "A source-target example is concatenated into one sentence with a special separator token between the two halves, and the model is trained as a plain next-token language model over the whole thing.", "explanation": "A sequence-transduction example with source (m_1, ..., m_n) and target (y_1, ..., y_eta) is converted into a single token sequence (w_1, ..., w_{n+eta+1}) = (m_1, ..., m_n, delta, y_1, ..., y_eta), where delta is a special separator token marking the boundary. Training then maximizes the ordinary autoregressive factorization p(w_1, ..., w_{n+eta}) = product over j of p(w_j | w_1, ..., w_{j-1}), with the usual causal masking in self-attention so position j cannot see positions after it. A consequence the paper highlights: because the loss covers every position, error signals are propagated from the input time-steps as well as the output time-steps - the model is also being asked to predict the source tokens, not just the target. At inference the source tokens are supplied as a prefix and the target is generated autoregressively from the separator onward, exactly as a language model continues a prompt; here decoding used beam search of size 4 with length penalty alpha = 0.6, continuing until an end-of-sequence token. Text on both sides used the same sub-word vocabulary of 32,000 tokens, so source and target live in one token space and one embedding table. The scheme requires no architectural machinery for conditioning beyond the separator token and the shared position space.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.2.3, the two displayed equations defining the concatenated sentence and the next-word factorization; tokenization in Section 4.2.1; decoding settings in Section 5.2.", "ownerPaper": "1801.10198", "sources": {"paperId": "1801.10198", "note": "Section 4.2.3, the two displayed equations defining the concatenated sentence and the next-word factorization; tokenization in Section 4.2.1; decoding settings in Section 5.2.", "sections": [], "pages": []}}, {"id": "long-input-scaling-comparison", "name": "Where the decoder-only stack pays off: long inputs", "tier": "minor", "parent": null, "summary": "The stated motivation for dropping the encoder is input length: the encoder-decoder transformer stopped learning at a few thousand input tokens, while the single-stack version kept improving further out.", "explanation": "The task studied is multi-document summarization with very long inputs - up to L = 11000 sub-word tokens of concatenated reference paragraphs mapped to outputs typically under 500 tokens - so input length is the binding constraint. An RNN encoder-decoder with attention baseline scored test perplexity 5.05 and ROUGE-L 12.7 at L = 500. The transformer encoder-decoder improved up to roughly L = 500-1000 (perplexity 2.47, ROUGE-L 34.2 at L = 500) and, the paper reports, was unable to learn at L = 2000. This is what motivated the decoder-only model, which kept learning and improving up to L = 4000 (perplexity 2.22, ROUGE-L 33.6) before exhausting memory on 16GB P100 GPUs. So the argument for the variant is not that it is a better model in general but that, at equal hyper-parameters, halving the stack lets a fixed memory budget cover a much longer context, and the self-attention span still spans the entire source-plus-target sequence. The paper measures with per-wordpiece perplexity and ROUGE-L F1, and reports that on this task optimizing perplexity correlated with ROUGE and human judgment - a correlation it flags as possibly specific to the uniform style of the target text.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 1 (Introduction); Section 5.3 paragraph 'Abstractive model architecture and input length'; Table 4 and Figure 3; evaluation metrics in Section 5.1.", "ownerPaper": "1801.10198", "sources": {"paperId": "1801.10198", "note": "Section 1 (Introduction); Section 5.3 paragraph 'Abstractive model architecture and input length'; Table 4 and Figure 3; evaluation metrics in Section 5.1.", "sections": [], "pages": []}}, {"id": "memory-compressed-attention", "name": "Memory-compressed attention", "tier": "minor", "parent": null, "summary": "A self-attention variant that shrinks the number of keys and values with a strided convolution after projection, leaving the queries untouched, so the attention matrix gets smaller by a fixed compression factor while still mixing information across the whole sequence.", "explanation": "Standard attention computes Attention(Q, K, V) = softmax(Q K^T / sqrt(d_k)) V, whose activation cost grows with the product of the number of queries and the number of keys. Here, after tokens are projected into query, key, and value embeddings, the key and value sequences are passed through a strided convolution that reduces their length; the query sequence is left at full length. With convolution kernels of size 3 and stride 3, the key/value count drops by roughly a factor of 3, dividing the number of attention activations by the same factor. Unlike block-restricted schemes, this layer still lets every query see a (compressed) summary of the entire sequence, so global information can move across the whole input. Causal masking is added so queries cannot attend to future keys and values, keeping the layer usable inside an autoregressive stack - though compressing keys across positions makes that masking coarser than in unmodified self-attention. The paper presents this alongside a block-local variant, and reports that together the two allow sequences about 3x longer than the plain decoder-only model.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.2.4 (Transformer Decoder with Memory-Compressed Attention), including the Attention(Q, K, V) equation; Figure 1 (middle panel).", "ownerPaper": "1801.10198", "sources": {"paperId": "1801.10198", "note": "Section 4.2.4 (Transformer Decoder with Memory-Compressed Attention), including the Attention(Q, K, V) equation; Figure 1 (middle panel).", "sections": [], "pages": []}}, {"id": "local-attention-blocks-lmlml", "name": "Block-local attention and the LMLML stack", "tier": "minor", "parent": null, "summary": "Tokens are split into fixed-size blocks and attention runs inside each block independently, making activation cost linear in sequence length; the final network alternates local and memory-compressed layers in a five-layer stack.", "explanation": "In the local-attention layer, the token sequence is divided into blocks of similar length - 256 tokens in these experiments - and attention is performed within each block independently, after which the per-block outputs are concatenated back into a full-length sequence. Because the attention cost per block is constant, total activations grow linearly rather than quadratically with sequence length. The trade-off is that a local layer only captures information inside its block, which is why it is interleaved with memory-compressed layers that can exchange information globally. The final architecture (T-DMCA) is a 5-layer network in the pattern LMLML, alternating local-attention (L) layers with [[memory-compressed-attention|memory-compressed attention]] (M) layers, in place of the usual stack of identical layers; causal masking is applied in both layer types. Some configurations also insert one mixture-of-experts layer to add capacity without proportional compute, using 128 or 256 experts. With these modifications the model trained at L = 11000 (perplexity 2.05, ROUGE-L 36.2 without the mixture-of-experts layer; 1.93 and 37.9 with 128 experts), and the best configuration used 256 experts at L = 7500 for perplexity 1.90 and ROUGE-L 38.8 - 256 experts at L = 11000 did not fit in memory.", "prerequisites": [], "sectionIds": [], "floor": false, "citedFrom": null, "sourceNote": "Section 4.2.4; Figure 1 (right panel, local attention); results in Table 4 and Figure 3.", "ownerPaper": "1801.10198", "sources": {"paperId": "1801.10198", "note": "Section 4.2.4; Figure 1 (right panel, local attention); results in Table 4 and Figure 3.", "sections": [], "pages": []}}], "items": [], "edges": [], "themes": [], "pages": [], "narrative": null, "insights": null, "refs": {"accessed": []}};
